// app/[locale]/calculadoras/[id]/page.tsx
'use client';

import { useState } from 'react';
import { useTranslations } from 'next-intl';
import { Calculator } from '@/lib/calculators/{id}';

export default function CalculatorPage() {
  const t = useTranslations('calculators');
  const [inputs, setInputs] = useState({});
  const [result, setResult] = useState(null);

  const handleCalculate = () => {
    const calculatedResult = Calculator.formula(inputs);
    setResult(calculatedResult);
  };

  return (
    <div className="calculator-container">
      <h1>{t('name')}</h1>
      <p>{t('description')}</p>

      {/* Input fields */}
      {Calculator.inputs.map(input => (
        <InputField key={input.id} {...input} onChange={handleChange} />
      ))}

      <button onClick={handleCalculate}>{t('calculate')}</button>

      {/* Result display */}
      {result && (
        <ResultDisplay result={result} interpretation={Calculator.interpretation} />
      )}

      {/* Citations */}
      <Citations refs={Calculator.citations} />

      {/* Disclaimer */}
      <Disclaimer text={Calculator.disclaimer} />
    </div>
  );
}
